def UnfoldingWorks : Prop :=
  ∀ (I O : Type) (N : Network I O) (T : ℕ),
    (N.unfold T).LoopFree ∧ Network.AgreeAlways (N.unfold T) N ∧ (N.unfold T).size = T * N.size

def SubstitutionFalsifies : Prop :=
  ∀ (P D E R : Type) (t : Testing P D E R) (r : R),
    t.SubstitutionAt r → ∀ o ∈ t.Datasets, t.rep o = r → t.FalsificationAt o
